-- Art - contrefacons (27)
                   detail_contrefacon, est_contrefacon_de)
SELECT 'art', f.nom, f.nom_vo, f.image_url, f.type_art, f.detail, vrai.id
FROM (VALUES
    ('toile académique', 'toile académique (contrefacon)', 'academic painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtVitruvianManFake.png', 'painting', 'Tâche en haut à droite du tableau.'),
    ('toile célèbre', 'toile célèbre (contrefacon)', 'famous painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtMonaLisaFake.png', 'painting', 'Les sourcils du personnage.'),
    ('toile charmante', 'toile charmante (contrefacon)', 'quaint painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtMilkmaidFake.png', 'painting', 'La quantité de lait versé.'),
    ('toile classique', 'toile classique (contrefacon)', 'basic painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtBlueBoyFake.png', 'painting', 'La frange du personnage.'),
    ('toile détaillée', 'toile détaillée (contrefacon)', 'detailed painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtAjisaisoukeizuFake.png', 'painting', 'Les couleurs des fleurs.'),
    ('toile effrayante', 'toile effrayante (contrefacon)', 'scary painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtOotaniOnijiFake.png', 'painting', 'Les sourcils du personnage.'),
    ('toile émouvante', 'toile émouvante (contrefacon)', 'moving painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtBirthVenusFake.png', 'painting', 'L''arbre en arrière-plan.'),
    ('toile gracieuse', 'toile gracieuse (contrefacon)', 'graceful painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtMikaeriFake.png', 'painting', 'La femme est plus grande.'),
    ('toile hivernale', 'toile hivernale (contrefacon)', 'scenic painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtHunterSnowFake.png', 'painting', 'Il manque un personnage.'),
    ('toile incroyable', 'toile incroyable (contrefacon)', 'amazing painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtNightWatchFake.png', 'painting', 'L''homme au centre n''a pas de chapeau.'),
    ('toile nacrée', 'toile nacrée (contrefacon)', 'wistful painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtPearlEarringFake.png', 'painting', 'La forme de la perle.'),
    ('toile potagère', 'toile potagère (contrefacon)', 'jolly painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtSummerFake.png', 'painting', 'La fleur en bas à droite.'),
    ('toile royale', 'toile royale (contrefacon)', 'serene painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtPortraitCeciliaFake.png', 'painting', 'La couleur de l''animal.'),
    ('toile solennelle', 'toile solennelle (contrefacon)', 'solemn painting (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtLasMeninasFake.png', 'painting', 'La position du bras du personnage.'),
    ('partie d. de toile sauvage', 'partie d. de toile sauvage (contrefacon)', 'wild painting right half (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtFuujinFake.png', 'painting', 'La couleur du personnage.'),
    ('partie g. de toile sauvage', 'partie g. de toile sauvage (contrefacon)', 'wild painting left half (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrArtRaijinFake.png', 'painting', 'La couleur du personnage.'),
    ('sculpture déterminée', 'sculpture déterminée (contrefacon)', 'rock-head statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureOlmecaHeadFake.png', 'sculpture', 'Le sourire du visage.'),
    ('sculpture mystérieuse', 'sculpture mystérieuse (contrefacon)', 'mystic statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureNefertitiFake.png', 'sculpture', 'Le buste porte une boucle d''oreille.'),
    ('sculpture singulière', 'sculpture singulière (contrefacon)', 'tremendous statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureHoumuwuDingFake.png', 'sculpture', 'Une anse est présente.'),
    ('statue athlétique', 'statue athlétique (contrefacon)', 'robust statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureDiskobolosFake.png', 'sculpture', 'Une montre est présente sur le poignet droit.'),
    ('statue féminine', 'statue féminine (contrefacon)', 'beautiful statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureMiloFake.png', 'sculpture', 'Le personnage porte un collier.'),
    ('statue guerrière', 'statue guerrière (contrefacon)', 'warrior statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureHeibayoFake.png', 'sculpture', 'Les mains reposent sur un objet.'),
    ('statue héroïque', 'statue héroïque (contrefacon)', 'valiant statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureSamothraceFake.png', 'sculpture', 'La position de la statue est inversée.'),
    ('statue majestueuse', 'statue majestueuse (contrefacon)', 'gallant statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureDavidFake.png', 'sculpture', 'Le personnage porte un livre.'),
    ('statue maternelle', 'statue maternelle (contrefacon)', 'motherly statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureCapitoliniFake.png', 'sculpture', 'La langue du loup est sortie.'),
    ('statuette antique', 'statuette antique (contrefacon)', 'ancient statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureDoguuFake.png', 'sculpture', 'Les antennes de la statuette.'),
    ('tablette édifiante', 'tablette édifiante (contrefacon)', 'informative statue (fake)', 'https://acnhcdn.com/latest/FtrIcon/FtrSculptureRosettaStoneFake.png', 'sculpture', 'La couleur de la tablette est bleue.')
) AS f(nom_oeuvre, nom, nom_vo, image_url, type_art, detail)
JOIN items vrai
  ON vrai.categorie = 'art'
 AND vrai.est_contrefacon_de IS NULL
 AND vrai.nom = f.nom_oeuvre;

COMMIT;

-- La vue materialisee a ete creee sur une base vide : son total d'items
-- est encore a zero tant qu'on ne la rafraichit pas.
REFRESH MATERIALIZED VIEW mv_classement;
